class UnionFind {
    constructor() {
        this.parents = new Map();
        this.sizes = new Map();
    }

    union(a, b) {
        const fa = this.find(a);
        const fb = this.find(b);
        if (fa !== fb) {
            this.parents.set(fa, fb);
            const sizeFb = this.sizes.has(fb) ? this.sizes.get(fb) : 1;
            const sizeFa = this.sizes.has(fa) ? this.sizes.get(fa) : 1;
            this.sizes.set(fb, sizeFb + sizeFa);
        }
    }

    find(a) {
        const getOrDefault = (value) => this.parents.has(value) ? this.parents.get(value) : value;
        let parent = getOrDefault(a);
        while (parent !== getOrDefault(parent)) {
            this.parents.set(parent, getOrDefault(getOrDefault(parent)));
            parent = this.parents.get(parent);
        }
        return parent;
    }

    connected(a, b) {
        return this.find(a) === this.find(b);
    }

    getSize(a) {
        const root = this.find(a);
        return this.sizes.has(root) ? this.sizes.get(root) : 1;
    }
}

