class BinaryIndexedTree {
    constructor(arg) {
        if (Array.isArray(arg)) {
            const nums = arg;
            this.bit = new Array(nums.length + 1).fill(0);
            const prefix = new Array(this.bit.length).fill(0);
            for (let i = 1; i <= nums.length; i++) {
                prefix[i] = prefix[i - 1] + nums[i - 1];
                this.bit[i] = prefix[i] - prefix[i - BinaryIndexedTree.lowbit(i)];
            }
        } else {
            const n = arg;
            this.bit = new Array(n + 1).fill(0);
        }
    }

    query(index) {
        let result = 0;
        let i = index + 1;
        while (i > 0) {
            result += this.bit[i];
            i -= BinaryIndexedTree.lowbit(i);
        }
        return result;
    }

    update(index, x) {
        const value = this.query(index) - this.query(index - 1);
        this.add(index, x - value);
    }

    add(index, x) {
        let i = index + 1;
        while (i < this.bit.length) {
            this.bit[i] += x;
            i += BinaryIndexedTree.lowbit(i);
        }
    }

    toString() {
        const arr = new Array(this.bit.length - 1);
        for (let i = 0; i < arr.length; i++) {
            arr[i] = this.query(i) - this.query(i - 1);
        }
        return JSON.stringify(arr);
    }

    static lowbit(x) {
        return x & -x;
    }
}

