    constructor(nums) {
        this.nums = nums;
        const n = nums.length;
        const logN = SparseTableMax.numberOfTrailingZeros(SparseTableMax.highestOneBit(n));
        this.st = Array.from({ length: n * 2 }, () => new Array(logN + 1).fill(0));
        for (let i = 0; i < n; i++) {
            this.st[i][0] = nums[i];
        }
        for (let j = 1; j <= logN; j++) {
            for (let i = 0; i < n; i++) {
                this.st[i][j] = this.st[i][j - 1];
                const shift = 1 << (j - 1);
                if (i + shift < n) {
                    this.st[i][j] = Math.max(this.st[i][j], this.st[i + shift][j - 1]);
                }
            }
        }
    }

    query(left, right) {
        if (left > right) return -1;
        const len = right - left + 1;
        const k = SparseTableMax.numberOfTrailingZeros(SparseTableMax.highestOneBit(len));
        return Math.max(this.st[left][k], this.st[right - (1 << k) + 1][k]);
    }

    static highestOneBit(x) {
        let v = x;
        v |= v >> 1;
        v |= v >> 2;
        v |= v >> 4;
        v |= v >> 8;
        v |= v >> 16;
        return v - (v >>> 1);
    }

    static numberOfTrailingZeros(x) {
        if (x === 0) return 32;
        let n = 0;
        let v = x;
        while ((v & 1) === 0) {
            n++;
            v >>>= 1;
        }
        return n;
    }
}

