class PrefixSum2D {
    constructor(grid) {
        this.grid = grid;
        const m = grid.length;
        const n = grid[0].length;
        this.prefix = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
        for (let i = 0; i < m; i++) {
            let row = 0;
            for (let j = 0; j < n; j++) {
                row += grid[i][j];
                this.prefix[i + 1][j + 1] = this.prefix[i][j + 1] + row;
            }
