function unify(nums) {
    const sorted = [...nums].sort((a, b) => a - b);
    const numToIndex = new Map();
    sorted.forEach((num, idx) => {
        if (!numToIndex.has(num)) numToIndex.set(num, idx);
    });
    return nums.map(num => numToIndex.get(num));
}

function fastPow(a, exp, mod) {
    let result = 1n % mod;
    let base = a % mod;
    let remain = exp;
    while (remain !== 0n) {
        if (remain % 2n === 1n) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        remain /= 2n;
    }
    return result;
}

