class BinaryIndexedTree {
    constructor(arg) {
        if (typeof arg === 'number') {
            this.bit = new Array(arg + 1).fill(0);
        } else {
            const nums = arg;
            this.bit = new Array(nums.length + 1).fill(0);
            const prefix = new Array(this.bit.length).fill(0);
            for (let i = 1; i <= nums.length; i++) {
                prefix[i] = prefix[i - 1] + nums[i - 1];
                this.bit[i] = prefix[i] - prefix[i - this.lowbit(i)];
            }
        }
    }

    query(index) {
        let result = 0;
        let i = index + 1;
        while (i > 0) {
            result += this.bit[i];
            i -= this.lowbit(i);
        }
        return result;
    }

    update(index, x) {
        const value = this.query(index) - this.query(index - 1);
        this.add(index, x - value);
    }

    add(index, x) {
        let i = index + 1;
        while (i < this.bit.length) {
            this.bit[i] += x;
            i += this.lowbit(i);
        }
    }

    toString() {
        const arr = new Array(this.bit.length - 1);
        for (let i = 0; i < arr.length; i++) {
            arr[i] = this.query(i) - this.query(i - 1);
        }
        return JSON.stringify(arr);
    }

    lowbit(x) {
        return x & -x;
    }
}

class BinaryIndexedTreeMax {
    constructor(n) {
        this.bit = new Array(n + 1).fill(0);
    }

    query(index) {
        let result = 0;
        let i = index + 1;
        while (i > 0) {
            result = Math.max(result, this.bit[i]);
            i -= this.lowbit(i);
        }
        return result;
    }

    update(index, x) {
        let i = index + 1;
        while (i < this.bit.length) {
            this.bit[i] = Math.max(this.bit[i], x);
            i += this.lowbit(i);
        }
    }

    lowbit(x) {
        return x & -x;
    }
}

class SparseTableMax {
    constructor(nums) {
        this.nums = nums;
        const n = nums.length;
        const logN = Math.floor(Math.log2(n));
        this.st = new Array(n * 2);
        for (let i = 0; i < this.st.length; i++) {
            this.st[i] = new Array(logN + 1).fill(0);
        }
        for (let i = 0; i < n; i++) {
            this.st[i][0] = nums[i];
        }
        for (let j = 1; j <= logN; j++) {
            for (let i = 0; i < n; i++) {
                this.st[i][j] = this.st[i][j - 1];
                const idx = i + (1 << (j - 1));
                if (idx < n) {
                    this.st[i][j] = Math.max(this.st[i][j], this.st[idx][j - 1]);
                }
            }
        }
    }

    query(left, right) {
        if (left > right) return -1;
        const len = right - left + 1;
        const k = Math.floor(Math.log2(len));
        return Math.max(this.st[left][k], this.st[right - (1 << k) + 1][k]);
    }
}

