function lengthOfLIS(numsInput) {
    const nums = unify(numsInput);
    const bit = new BinaryIndexedTreeMax(nums.length + 1);
    let result = 0;
    for (const num of nums) {
        const len = bit.query(num - 1) + 1;
        bit.update(num, len);
        result = Math.max(result, len);
    }
    return result;
}

function unify(nums) {
    const sorted = [...nums].sort((a, b) => a - b);
    const numToIndex = new Map();
    sorted.forEach((num, index) => {
        numToIndex.set(num, index);
    });
    return nums.map((num) => numToIndex.get(num));
}

function fastPow(a, exp, mod) {
    let result = 1n % mod;
    let base = a % mod;
    let remain = exp;
    while (remain !== 0n) {
        if (remain % 2n === 1n) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        remain /= 2n;
    }
    return result;
}

