function requiredLen(n, x) {
    const MAX = 10000;
    const queue = toArrayDeque([x]);
    let step = 0;
    while (queue.length > 0) {
        const next = [];
        while (queue.length > 0) {
            const num = queue.shift();
            if (num < 0n) {
                return step;
            }
            const str = num.toString();
            if (str.length === n) {
                return step;
            }
            if (str.length > n) {
                continue;
            }
            const digits = new Array(10).fill(false);
            for (const ch of str) {
                const d = toDigit(ch);
                if (d <= 1 || digits[d]) {
                    continue;
                }
                digits[d] = true;
                next.push(num * BigInt(d));
            }
        }
        next.sort((a, b) => (a > b ? -1 : a < b ? 1 : 0));
        const limit = Math.min(MAX, next.length);
        for (let i = 0; i < limit; i++) {
            queue.push(next[i]);
        }
        step++;
    }
    return -1;
}

function requiredLen1(n, x) {
    const queue = toArrayDeque([x]);
    let step = 0;
    while (queue.length > 0) {
        const nextQueue = [];
        let maxLen = 0;
        while (queue.length > 0) {
            const num = queue.shift();
            if (num < 0n) {
                return step;
            }
            const str = num.toString();
            if (str.length === n) {
                return step;
            }
            if (str.length > n) {
                continue;
            }
            const digits = new Array(10).fill(false);
            for (const ch of str) {
                digits[toDigit(ch)] = true;
            }
            for (let d = 2; d < 10; d++) {
                if (!digits[d]) continue;
                const nextNum = num * BigInt(d);
                const nextStr = nextNum.toString();
                nextQueue.push([nextNum, nextStr]);
                if (nextStr.length > maxLen) maxLen = nextStr.length;
            }
        }
        for (const [num, str] of nextQueue) {
            queue.push(num);
        }
        step++;
    }
    return -1;
}

