function requiredLen(n, x) {
    const MAX = 10000;
    const queue = [x];
    let head = 0;
    let step = 0;
    while (head < queue.length) {
        const next = [];
        const end = queue.length;
        while (head < end) {
            const num = queue[head++];
            if (num < 0n) {
                return step;
            }
            const str = num.toString();
            if (str.length === n) {
                return step;
            }
            if (str.length > n) {
                continue;
            }
            const digits = new Array(10).fill(false);
            for (const ch of str) {
                const d = toDigit(ch);
                if (d <= 1 || digits[d]) {
                    continue;
                }
                digits[d] = true;
                next.push(num * BigInt(d));
            }
        }
        next.sort((a, b) => (a < b ? 1 : a > b ? -1 : 0));
        const limit = Math.min(MAX, next.length);
        for (let i = 0; i < limit; i++) {
            queue.push(next[i]);
        }
        step++;
    }
    return -1;
}

