    fun query(index: Int): Int {
        var result = 0
        var i = index + 1
        while (i > 0) {
            result = Math.max(result, bit[i])
            i -= lowbit(i)
        }
        return result
    }

    fun update(index: Int, x: Int) {
        var i = index + 1
        while (i < bit.size) {
            bit[i] = Math.max(bit[i], x)
            i += lowbit(i)
        }
    }

    private fun lowbit(x: Int): Int {
        return x.and(-x)
    }
}

class SparseTableMax(private val nums: IntArray) {

    private val st: Array<IntArray>

    init {
        val n = nums.size
        val logN = Integer.numberOfTrailingZeros(Integer.highestOneBit(n))
        this.st = Array(n * 2) { IntArray(logN + 1) }
        for (i in 0 until n) {
            st[i][0] = nums[i]
        }
        for (j in 1 until logN + 1) {
            for (i in 0 until n) {
                st[i][j] = st[i][j - 1]
                if (i + 1.shl(j - 1) < n) {
                    st[i][j] = Math.max(st[i][j], st[i + 1.shl(j - 1)][j - 1])
                }
            }
        }
    }

    fun query(left: Int, right: Int): Int {
        if (left > right) {
            return -1
        }
        val len = right - left + 1
        val k = Integer.numberOfTrailingZeros(Integer.highestOneBit(len))
        return Math.max(st[left][k], st[right - 1.shl(k) + 1][k])
    }
}

